 const string Key="ROM.MainMenuReview";static string Output=>Path.GetFullPath("Logs/MainMenuReview");static readonly string[] Saved={"ROM.Character.ActiveId",AbilityController.Preference,PlayerInstance.ClassPreference,"_playerPrefs_Username","_playerPrefs_CharacterSkinID",RiftControls.Preference};static int step;static double next,began;static RiftHub hub;static Keyboard keyboard;static Mouse mouse;static RiftAchievementCapture shot;static readonly List<string> result=new List<string>();static readonly Dictionary<InputActionAsset,InputDevice[]> devices=new Dictionary<InputActionAsset,InputDevice[]>();static int playClicks;static bool playReady;static string character;static int oldBackground,oldEditorInput;
  static RiftMainMenuReview(){EditorApplication.playModeStateChanged+=Changed;}
 static bool IntKey(string key)=>key==AbilityController.Preference||key==PlayerInstance.ClassPreference||key=="_playerPrefs_CharacterSkinID";
 public static void Run(){if(SessionState.GetBool(Key,false))return;for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new Exception("Unsaved scene; refusing review");foreach(var key in Saved){SessionState.SetBool(Key+key+"Exists",PlayerPrefs.HasKey(key));SessionState.SetString(Key+key,IntKey(key)?PlayerPrefs.GetInt(key).ToString():PlayerPrefs.GetString(key));}SessionState.SetString(Key+"Nickname",UserSettings.UserNickname);SessionState.SetInt(Key+"Skin",UserSettings.CharacterSkinID);SessionState.SetString(Key+"Sources",SourceHash());SessionState.SetBool(Key,true);Directory.CreateDirectory(Output);SetSize(1920,1080,true);EditorSceneManager.OpenScene("Assets/ROM/Scenes/MainMenu.unity");EditorApplication.isPlaying=true;}
 static void Changed(PlayModeStateChange state){if(!SessionState.GetBool(Key,false))return;if(state==PlayModeStateChange.EnteredPlayMode){step=0;next=began=EditorApplication.timeSinceStartup;EditorApplication.update+=Tick;}if(state==PlayModeStateChange.EnteredEditMode){foreach(var key in Saved){if(!SessionState.GetBool(Key+key+"Exists",false))PlayerPrefs.DeleteKey(key);else if(IntKey(key))PlayerPrefs.SetInt(key,int.Parse(SessionState.GetString(Key+key,"0")));else PlayerPrefs.SetString(key,SessionState.GetString(Key+key,""));}UserSettings.UserNickname=SessionState.GetString(Key+"Nickname","");UserSettings.CharacterSkinID=SessionState.GetInt(Key+"Skin",1);PlayerPrefs.Save();try{RestoreSize();}catch(Exception e){File.AppendAllText(Path.Combine(Output,"validation.txt"),"\nFAIL Game View restore: "+e);SessionState.SetInt(Key+"Result",1);}SessionState.SetBool(Key,false);EditorApplication.Exit(SessionState.GetInt(Key+"Result",1));}}
 static string SourceHash(){string root="Assets/ROM/Characters/Warrior/";string[] files={root+"WarriorLobby.prefab",root+"WarriorPlayer.prefab",root+"WarriorLocomotion.controller","Assets/ROM/Scenes/MainMenu.unity","Assets/ROM/Levels/map_rom_horde.unity"};return string.Join("|",files.Select(p=>{using(var stream=File.OpenRead(p))using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream));}));}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);result.Add("PASS "+message);}
