 static void At(Transform target,ushort buttons=0){Canvas.ForceUpdateCanvases();var rect=(RectTransform)target;var point=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center));InputSystem.QueueStateEvent(mouse,new MouseState{position=point,buttons=buttons});}
 static void Advance(double seconds=.4){step++;next=EditorApplication.timeSinceStartup+seconds;}
 static void Capture(string name){RiftAbilityTooltip.HideAll();shot=new RiftAchievementCapture();shot.Save(Path.Combine(Output,name+".png"),hub?hub:(MonoBehaviour)RiftVideoSettings.Instance);}
 static bool SavedShot(){if(shot==null||!shot.Done)return false;if(shot.Error!=null)throw shot.Error;return true;}
 static void InputSetup(){oldBackground=(int)InputSystem.settings.backgroundBehavior;oldEditorInput=(int)InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;keyboard=InputSystem.AddDevice<Keyboard>();keyboard.MakeCurrent();mouse=InputSystem.AddDevice<Mouse>();mouse.MakeCurrent();foreach(var module in UnityEngine.Object.FindObjectsByType<UnityEngine.InputSystem.UI.InputSystemUIInputModule>(FindObjectsSortMode.None)){var asset=module.actionsAsset;if(!asset||devices.ContainsKey(asset))continue;devices[asset]=asset.devices.HasValue?asset.devices.Value.ToArray():null;asset.devices=new InputDevice[]{keyboard,mouse};}}
